// Generated by apps/web/fonts/build_scripts.py (`task fonts`). Do not edit by hand.
// Code points the bundled proto-cuneiform and hieroglyph fonts really draw.

const SPANS: Record<string, ReadonlyArray<readonly [number, number]>> = {
  // 2934 code points in 15 spans
  "proto-cuneiform": [
    [0x12550, 0x12686], [0x12690, 0x12bff], [0xf00da, 0xf00ef], [0xf00f5, 0xf0107], [0xf010a, 0xf010f], [0xf0124, 0xf012d],
    [0xf2000, 0xf21b7], [0xf21b9, 0xf22af], [0xf2400, 0xf251d], [0xf251f, 0xf2538], [0xf253a, 0xf253a], [0xf253d, 0xf253e],
    [0xf2541, 0xf2545], [0xf2d00, 0xf2da4], [0xf5500, 0xf5501],
  ],
  // 5105 code points in 2 spans
  "egyptian": [
    [0x13000, 0x13455], [0x13460, 0x143fa],
  ],
}

/** True when the script's bundled font has a real glyph for the code point (scripts without a table: always). */
export function scriptDraws(script: string, cp: number): boolean {
  const spans = SPANS[script]
  if (!spans) return true
  let lo = 0
  let hi = spans.length - 1
  while (lo <= hi) {
    const mid = (lo + hi) >> 1
    const [a, b] = spans[mid]!
    if (cp < a) hi = mid - 1
    else if (cp > b) lo = mid + 1
    else return true
  }
  return false
}
